"""manuscript_text.py: builds the manuscript as a list of blocks using numbers read from output/results.pkl.
Block types: title, h1, h2, h3, p, note (italic centered call-out). Citation markers: [[c:key;key]] parenthetical, [[n:key]] narrative."""
import pickle, re
import numpy as np, pandas as pd
from lib import P1

R = pickle.load(open(f'{P1}/output/results.pkl', 'rb'))
d = pd.read_csv(f'{P1}/data_clean/analysis_child_2000cohort.csv')
h = pd.read_stata(f'{P1}/../health2004t.dta', convert_categoricals=False)
H_SD = h[h.height.between(120, 200)].groupby(['sex', 'byear']).height.std().mean()   # cm per SD of height z

T2, T3, T4, T5, T6o, T6n = R['T2'], R['T3'], R['T4'], R['T5'], R['T6_oster'], R['T6_nco']
def g(df, **kw):
    q = df
    for k, v in kw.items(): q = q[q[k] == v]
    assert len(q) == 1, kw
    return q.iloc[0]
def f2(v): return f'{v:.2f}'
def f3(v): return f'{v:.3f}'
def pf(p): return 'p < 0.001' if p < 0.001 else f'p = {p:.3f}'
def ci(r): return f'95% CI {r.lo:.2f} to {r.hi:.2f}'
def pct(v): return f'{100 * v:.1f}%'
def t1(label): return g(R['T1'], Variable=label)

bwh = g(T2, exposure='bw_c', outcome='z_height04'); bwc = g(T2, exposure='bw_c', outcome='z_cogacad')
lbh = g(T2, exposure='lbw_est', outcome='z_height04'); lbc = g(T2, exposure='lbw_est', outcome='z_cogacad')
bw_ind = T2[(T2.exposure == 'bw_c') & (~T2.outcome.isin(['z_height04', 'z_cogacad']))]
assert (bw_ind.p > 0.05).all() and bwh.p < 0.001 and bwc.p > 0.10          # guards for claims made in the text
cm1, cm2 = bwh.b * H_SD, abs(lbh.b) * H_SD
inv = g(T3, exposure='bw_c', outcome='invest'); bks = g(T3, exposure='bw_c', outcome='books_z'); perf = g(T3, exposure='bw_c', outcome='mother_rated_perf')
lbks = g(T3, exposure='lbw_est', outcome='books_z'); lasp = g(T3, exposure='lbw_est', outcome='edu_aspire'); lcol = g(T3, exposure='lbw_est', outcome='asp_college')
pasp = g(T3, exposure='preterm', outcome='edu_aspire'); pcol = g(T3, exposure='preterm', outcome='asp_college')
hpi = g(T3, exposure='health_vs_peers', outcome='invest')
assert lbks.p < 0.001 and lbks.q < 0.05 and pasp.p < 0.05 and hpi.p < 0.001
old = T4[T4.moderator.isin(['oldage_high', 'rely_sons_agree'])]
assert (old.b_int > 0).sum() == 6 and (old[old.p_int < 0.05].b_int > 0).all() and (old.p_int < 0.05).sum() == 3
assert (T5[T5.outcome == 'z_cogacad'].b > 0).all() and (T5[T5.outcome == 'z_cogacad'].p > 0.05).all()
oa = g(T4, moderator='oldage_high', outcome='z_cogacad'); rs_h = g(T4, moderator='rely_sons_agree', outcome='z_height04')
rs_i = g(T4, moderator='rely_sons_agree', outcome='invest'); sl_i = g(T4, moderator='ses_low', outcome='invest')
assert oa.p_int < 0.05 and rs_h.p_int < 0.01 and sl_i.p_int < 0.01 and (T4.q_all > 0.05).sum() >= 25
bh = g(T5, spec='Baseline', outcome='z_height04'); bc = g(T5, spec='Baseline', outcome='z_cogacad')
rng_c = T5[T5.outcome == 'z_cogacad']; rng_h = T5[T5.outcome == 'z_height04']
ipw = R['T5_ipw'].set_index('outcome')
ost_c = T6o.set_index('outcome').loc['z_cogacad']; ost_h = T6o.set_index('outcome').loc['z_height04']; ost_i = T6o.set_index('outcome').loc['invest']
ev = R['T6_evalue'].set_index('outcome')
nco = T6n.set_index('outcome')
att = R['A_attrition'].set_index('sample')
n_all = len(d); n_bw = int(d.bw_kg.notna().sum())
n_cog = int(d.z_cogacad.notna().sum()); n_ht = int(d.z_height04.notna().sum())
share_home = d.home_birth.mean()
sex_miss = d.sex_missing.mean()
heap = R['heaping']['share_3kg']

LBW_LAB = 'Low birth weight, maternal category "light"'
FATHER = "Father's age"
MOTHER = "Mother's age"
TITLE = 'Birth Weight, Parental Investment, and Child Development in Rural China: Evidence from the Gansu Survey of Children and Families'
KEYWORDS = 'Birth weight; Child development; Parental investment; Old-age support; Rural China; Developmental origins'

ABSTRACT = (
 f'Early-life health endowments may shape child development, yet evidence from poor rural settings is scarce, and little is known about how parents respond to weaker endowments when they expect to rely on children in old age. '
 f'Using the Gansu Survey of Children and Families (2,000 rural children aged 9 to 12 in 2000, followed to 2009), this study links maternal reports of birth weight and gestational age to cognitive and academic tests, measured height, and parental investment, with county fixed effects. '
 f'Each additional kilogram of birth weight is associated with {f2(bwh.b)} standard deviations (SD) greater height in adolescence ({ci(bwh)}). The estimate is robust to wild cluster bootstrap inference, attrition weights, and coefficient stability checks. '
 f'Associations with cognitive and academic scores have the same sign but are smaller and imprecise ({f2(bwc.b)} SD per kilogram; {ci(bwc)}). '
 f'Parental investment reinforces rather than offsets endowments: children estimated below 2.5 kg own fewer books and receive lower educational aspirations. '
 f'Exploratory interactions suggest steeper gradients where mothers expect substantial old-age support from children or favor reliance on sons. '
 f'Weak birth endowments leave lasting physical penalties and meet little parental compensation.')

def build():
    B = []
    A = B.append
    A(('title', TITLE))
    A(('h1', 'Abstract')); A(('p', ABSTRACT)); A(('p', f'Keywords: {KEYWORDS}'))
    # ------------------------------------------------------------------ 1 Introduction
    A(('h1', '1. Introduction'))
    A(('p', 'Conditions at birth are among the earliest and most persistent sources of inequality in child development. The fetal origins literature links lower birth weight and shorter gestation to poorer health, schooling, and labor market outcomes later in life [[c:Barker1990;Almond2011;Almond2018;Currie2009]]. Twin and sibling designs, which remove shared family background, find that birth weight predicts adult outcomes beyond what family circumstances explain [[c:Behrman2004;Black2007;Oreopoulos2008;Royer2009]]. Most of this evidence comes from high-income countries with birth registries. Evidence from poor rural populations, where low birth weight is more common and compensatory health care is scarcer, is thinner, and it rarely follows the same children from childhood into adolescence with both cognitive and physical measures [[c:Victora2008;Adair2013;GM2007]].'))
    A(('p', 'A second question concerns what families do after a weak start. In the Becker and Tomes tradition, parents allocate resources across children according to endowments, their own preferences for equality, and the expected returns to investment [[c:Becker1976;Behrman1982]]. Compensating investment narrows endowment gaps, whereas reinforcing investment widens them. Empirical studies report both patterns, depending on the investment measured and the setting [[c:Datar2010;Hsin2012;Yi2015;AlmondMazumder2013]]. Whether parents compensate or reinforce matters for the persistence of early disadvantage, because dynamic complementarity in skill formation implies that later investment is more productive for children who start with stronger skills [[c:Cunha2007;Heckman2006]].'))
    A(('p', 'The investment decision has a demographic dimension that existing work treats only implicitly. In rural China, formal old-age protection was thin in the period studied here, and parents expected financial support from children, especially sons [[c:Lee1998;Zimmer2003]]. Transfers from children insure parents against low retirement income even in urban China [[c:Cai2006]]. When children are the main source of old-age security, the returns to investing in a child accrue partly to the parents, and a weak child endowment lowers the expected return [[c:Caldwell1976]]. Parental expectations about old-age support therefore provide a way to link the endowment and investment literatures to population aging. Parents who expect to depend on their children have the strongest incentive to allocate resources efficiently, which should strengthen reinforcement, and the strongest stake in the child outcomes that determine later support.'))
    A(('p', 'This study examines these ideas with the Gansu Survey of Children and Families (GSCF), a longitudinal survey of rural children in one of the poorest provinces of China [[c:Hannum2007;Hannum2012]]. Mothers of 2,000 children aged 9 to 12 in 2000 reported birth weight, gestational age, and place of delivery. The same children were followed with standardized cognitive and academic tests in 2000, 2004, and 2009 and with a health examination in 2004. The analysis addresses three questions. First, does reported birth weight predict adolescent height and cognitive and academic performance? Second, do parents reinforce or compensate in their investments in learning? Third, are these patterns stronger where parents expect old-age support from children, and do they vary with household resources, child sex, and village environmental conditions?'))
    A(('p', 'The study makes three contributions. Empirically, it provides longitudinal evidence on birth endowments and child development from a poor rural population in northwest China, with a measured physical outcome that validates the maternal reports. Conceptually, it connects the reinforcement and compensation literature to intergenerational old-age contracts, an aging mechanism that has not been tested directly in this literature. Methodologically, it combines coefficient stability bounds, negative control outcomes, wild cluster bootstrap inference, and corrections for multiple testing to establish how much weight the estimates can bear. The design cannot support causal claims about birth weight, and the paper says so throughout. It documents robust associations, shows which are fragile, and identifies where stronger data are needed.'))
    # ------------------------------------------------------------------ 2 Background
    A(('h1', '2. Background and hypotheses'))
    A(('h2', '2.1 Birth endowments and child development'))
    A(('p', 'Birth weight and gestational age summarize fetal growth and are correlated with later cognitive performance, schooling, and health [[c:Almond2011;Currie2011]]. Reviews of preterm and very low birth weight cohorts report lower cognitive scores in childhood and adolescence [[c:Bhutta2002;Aarnoudse2009;Hack2002]]. Studies of broader birth weight ranges report smaller gradients [[c:Conley2000;Case2005;Strauss2000]]. Sibling and twin comparisons tend to find gradients that are smaller than cross-sectional estimates but generally positive [[c:Black2007;Royer2009;Almond2005;Figlio2014]]. Evidence from health interventions that raise survival and growth of vulnerable newborns points in the same direction [[c:Bharadwaj2013;Hoddinott2008]].'))
    A(('p', 'Two features of the evidence guide the empirical strategy. First, physical growth is the outcome most tightly tied to fetal growth, whereas cognitive outcomes depend on a longer chain of postnatal investments, so gradients for height should be larger and more precise than gradients for test scores [[c:Victora2008;Adair2013]]. Height is also a marker of early nutrition and later ability [[c:Case2008]]. Second, the social gradient in the consequences of poor health at birth is contested. Whether family resources cushion children against early shocks is debated [[c:Currie1999]], and advantaged families may instead convert strong endowments into larger gains, a pattern that matches reinforcement.'))
    A(('h2', '2.2 Parental investment: reinforcement or compensation'))
    A(('p', 'Models of parental allocation distinguish an efficiency motive, which directs resources to the child with the highest expected return, from an equity motive, which directs resources to the child who needs them most [[c:Becker1976;Behrman1982;Rosenzweig1988]]. Reinforcement follows from the efficiency motive and compensation from the equity motive. In the skill formation framework, dynamic complementarity strengthens the efficiency motive, because early skills raise the productivity of later investment [[c:Cunha2006;Cunha2007]]. Empirical tests rely largely on twin and sibling comparisons and report mixed results [[c:Datar2010;Hsin2012;Yi2015]]. In a setting where schooling is costly, school quality is uneven, and children contribute to household production, as in rural Gansu [[c:Hannum2006;Hannum2009;Adams2005]], resource constraints plausibly tilt parents toward reinforcement.'))
    A(('h2', '2.3 Old-age support expectations and investment in children'))
    A(('p', 'In demographic transition theory, the direction of intergenerational wealth flows shapes fertility and investment decisions [[c:Caldwell1976]]. In rural China in 2000, formal pensions covered few villagers, and children were the primary source of support in old age, with sons expected to carry most of the obligation [[c:Lee1998;Zimmer2003]]. A parent who expects substantial financial help from children has a direct financial stake in the child\'s later earnings, and a parent who expects that help from sons has a stake in the human capital of sons. These stakes sharpen the efficiency motive. The prediction is that endowment gradients in investment, and in the outcomes that investment produces, are steeper where old-age expectations are high.'))
    A(('h2', '2.4 Hypotheses'))
    A(('p', 'Hypothesis 1 states that higher birth weight predicts greater height in adolescence. Hypothesis 2 states that higher birth weight predicts higher cognitive and academic scores, with a gradient smaller than that for height. Hypothesis 3 states that parental investment in learning is higher for children with stronger birth endowments (reinforcement). Hypothesis 4 states that the gradients in Hypotheses 1 to 3 are steeper where mothers expect substantial old-age support from children or favor reliance on sons. The analysis also examines moderation by household resources, child sex, and village environmental conditions, without a directional prediction.'))
    # ------------------------------------------------------------------ 3 Data and methods
    A(('h1', '3. Data and methods'))
    A(('h2', '3.1 The Gansu Survey of Children and Families'))
    A(('p', f'The GSCF is a multi-level longitudinal study of rural children in 100 villages in 20 counties of Gansu province. The 2000 wave sampled {n_all:,} target children aged 9 to 12 through a multi-stage cluster design. Target children were surveyed again in 2004 and 2009, and a health examination was conducted in 2004. A new sample of children in the same villages was added in 2007, and a 2015 wave exists, but neither is used here because the 2007 sample is a different cohort and the 2015 child files are outside the analysis set. Mothers answered a questionnaire in 2000 that includes the birth items. The analysis uses the target children in the released linked files. The unit of analysis is the child, and village identifiers are available for clustering.'))
    A(('h2', '3.2 Measures'))
    A(('h3', '3.2.1 Birth endowments'))
    A(('p', f'In 2000, mothers reported whether the child was born at term, preterm, or post-term, or whether they did not know. They rated the child\'s birth weight as heavy, average, or light compared with other children, and estimated the weight in jin (one jin equals 0.5 kg). The estimated weight is available for {n_bw:,} children (mean {f2(t1("Estimated birth weight (kg)").Mean)} kg, SD {f2(t1("Estimated birth weight (kg)").SD)}). The primary exposure is birth weight in kilograms, centered at the sample median of 3.0 kg, so that coefficients give the difference associated with one additional kilogram. Secondary exposures are an indicator for an estimated weight below 2.5 kg ({pct(t1("Estimated birth weight below 2.5 kg").Mean)} of children), an indicator for the maternal category "light" ({pct(t1(LBW_LAB).Mean)}), and an indicator for preterm birth ({pct(t1("Preterm birth").Mean)}). Gestation was unknown to {pct(t1("Gestational age unknown").Mean)} of mothers, and these children are retained in the preterm comparison group, with a robustness check that drops them. The weight estimates show heaping at 3.0 kg ({pct(heap)} of reports), a pattern typical of retrospective recall that biases estimates toward zero if the heaping is noise.'))
    A(('h3', '3.2.2 Child outcomes'))
    A(('p', 'Cognitive and academic outcomes come from standardized tests administered by the survey team. In 2000, children took a cognitive test and an achievement test in either Chinese or mathematics, assigned by the parity of the household code. In 2004, they took Chinese and mathematics tests that differ by school level and a literacy test. In 2009, they took a literacy test, scored as the sum of item scores. Each score is standardized within test form, and the cognitive and academic composite is the average of the available standardized scores, required to include at least four of six, then re-standardized. Height was measured in the 2004 health examination and standardized within sex and birth year cells. One SD of height corresponds to about ' + f'{H_SD:.1f}' + ' cm in this sample.'))
    A(('h3', '3.2.3 Parental investment'))
    A(('p', 'The investment index averages four standardized items that mothers answered for the previous month: reading story books with the child, helping with homework, playing with the child, and taking the child to a bookstore or shop. Additional indicators are the number of books the child owns (logarithm, standardized), the educational level the mother hopes the child will reach, an indicator for aspiring to college, an indicator for expecting college, and the mother\'s rating of the child\'s school performance. Mothers also rated the child\'s health compared with village peers, which is a contemporaneous health measure rather than a birth measure.'))
    A(('h3', '3.2.4 Moderators and covariates'))
    A(('p', f'The old-age support moderator is an indicator that the mother expects to receive "a lot" of financial help from her children in the future ({pct(t1("Mother expects a lot of financial help in old age").Mean)} of mothers). A second moderator indicates agreement that parents should rely on sons for care in old age ({pct(t1("Agrees parents should rely on sons in old age").Mean)}). Household resources are summarized by an index that standardizes and averages seven items: satisfaction with the family\'s economic situation, relative standing in the village, sufficiency of income, food sufficiency, and ownership of a desk, a dictionary, and reading materials for the child. Village environmental conditions are measured in two ways: the mother\'s rating of the village environment for child growth, and the share of households in the village that draw drinking water from unpumped wells, rivers, lakes, or ponds, taken from the 2000 village survey. Controls are child age in single years (truncated at 9 and 13), sex (recorded in the 2004 files, with an indicator for the {pct(sex_miss)} of children with missing sex), parents\' ages, sibship size, first-born status, the presence of a brother, the household resource index, and county fixed effects.'))
    A(('h2', '3.3 Empirical strategy'))
    A(('h3', '3.3.1 Main specification'))
    A(('p', 'For child i in village v and county c, the main model is Y(ivc) = a + b B(i) + X(i)g + q(c) + e(ivc), where Y is a standardized outcome, B is a birth endowment, X is the vector of controls, and q(c) is a county fixed effect. Standard errors are clustered at the village level (100 clusters). Because the number of clusters is moderate and the county fixed effects absorb regional differences in health care, schooling, and altitude, robustness checks use a wild cluster bootstrap and clustering at the county level [[c:Cameron2008;Cameron2015]]. Heterogeneity is tested with interactions between birth weight and each moderator, and subgroup slopes are reported for interpretation.'))
    A(('h3', '3.3.2 Multiple testing and exploratory status'))
    A(('p', 'The analysis reports eight outcomes for each of four exposures, six investment measures for five predictors, and 28 interaction tests. Benjamini and Hochberg false discovery rate q-values are computed within each family of tests [[c:Benjamini1995]]. The analysis was not preregistered. Main-effect results for birth weight on height and cognitive and academic scores test Hypotheses 1 and 2. Interactions are exploratory and are interpreted against the corrected q-values.'))
    A(('h3', '3.3.3 Identification checks'))
    A(('p', 'Birth weight is not randomly assigned, and the estimates are associations. Four checks address the main threats. Coefficient stability bounds ask how strong selection on unobservables would have to be, relative to selection on the included controls, to explain away the estimate [[c:Altonji2005;Oster2019]]. E-values express the minimum strength of unmeasured confounding needed to account for a result [[c:VanderWeele2017]]. Negative control outcomes, such as parents\' ages and village characteristics, should be unrelated to a child\'s birth weight, so associations with them flag confounding or reporting bias. Finally, inverse probability weights correct for attrition between 2000 and the later waves, and the validation of maternal reports against measured height speaks to measurement error [[c:Bound2001;Adegboye2008]]. Sibling fixed effects and instruments are not feasible because the survey did not collect birth information for siblings and offers no credible instrument for birth weight.'))
    # ------------------------------------------------------------------ 4 Results
    A(('h1', '4. Results'))
    A(('h2', '4.1 Descriptive patterns'))
    A(('p', f'Table 1 presents descriptive statistics. Children were {f2(t1("Age in 2000 (years)").Mean)} years old on average in 2000, and {pct(t1("Female").Mean)} of the children with recorded sex were girls. Mothers estimated mean birth weight at {f2(t1("Estimated birth weight (kg)").Mean)} kg. {pct(share_home)} of births occurred at home and {pct(t1("Born in a clinic or hospital").Mean)} in a clinic or hospital. Mean household resources, investment, and outcomes differ little between children with an adverse birth (light or preterm) and others, which is why adjusted models are needed to read the gradients. Figure 1 shows the distribution of estimated birth weight and the county variation in the share below 2.5 kg, which ranges from near zero to about one in five. County fixed effects absorb this variation.'))
    A(('note', '[Insert Table 1 and Figure 1 about here]'))
    A(('p', f'Follow-up was high for the 2004 tests ({pct(d.obs04_test.mean())}) and the 2004 health examination ({pct(d.obs04_health.mean())}) and lower for the 2009 literacy test ({pct(d.obs09.mean())}). {n_cog:,} children have the cognitive and academic composite and {n_ht:,} have measured height. Higher birth weight predicts a lower probability of being measured in 2009 (logit coefficient {f2(att.loc["Literacy test observed in 2009","b_bw"])} per kg, {pf(att.loc["Literacy test observed in 2009","p_bw"])}) and a somewhat higher probability of height measurement in 2004 ({f2(att.loc["Height measured in 2004","b_bw"])}, {pf(att.loc["Height measured in 2004","p_bw"])}). Weighted estimates in Section 4.5 show that these patterns do not change the results.'))
    A(('h2', '4.2 Birth endowments and child development'))
    A(('p', f'Table 2 and Figure 2 report the main estimates. Birth weight is strongly and robustly associated with adolescent height. Each additional kilogram predicts {f2(bwh.b)} SD greater height ({ci(bwh)}; {pf(bwh.p)}; q = {f3(bwh.q)}), about {cm1:.1f} cm. An estimated birth weight below 2.5 kg predicts height lower by {f2(abs(lbh.b))} SD ({ci(lbh)}; {pf(lbh.p)}; q = {f3(lbh.q)}), about {cm2:.1f} cm. The maternal "light" category and preterm birth show weaker height associations, in line with the greater subjectivity of those reports. The height gradient also appears for body mass index, but not for hemoglobin (Supplementary Appendix). These results support Hypothesis 1.'))
    A(('p', f'Associations with cognitive and academic outcomes have the expected sign for continuous birth weight but are small and imprecise. The composite rises by {f2(bwc.b)} SD per kilogram ({ci(bwc)}; {pf(bwc.p)}). Individual outcomes range from {f2(bw_ind.b.min())} to {f2(bw_ind.b.max())} SD, and none passes conventional thresholds or survives correction for multiple testing. Below 2.5 kg, the composite is {f2(abs(lbc.b))} SD lower ({ci(lbc)}; {pf(lbc.p)}). The point estimates exclude large cognitive penalties (the upper confidence limit for the per-kilogram composite gradient is {f2(bwc.hi)} SD) but cannot rule out modest ones. Preterm birth is not consistently related to test scores: two of eight estimates have p below 0.10, with opposite signs, and neither has a q-value below 0.05. Hypothesis 2 therefore receives partial support: the signs agree with the literature, the magnitude is about {f2(bwc.b / bwh.b)} times the height gradient, and the data lack the precision to distinguish a modest gradient from none.'))
    A(('note', '[Insert Table 2 and Figure 2 about here]'))
    A(('p', 'Figure 3 plots partial residuals. The height gradient is visible across the distribution of residual birth weight, and the cognitive and academic gradient is shallower with wide bands. A nonparametric check with birth weight bins shows the height penalty concentrated below 2.5 kg and above 3.0 kg gains of similar size (Supplementary Appendix), so the linear specification summarizes the pattern adequately without implying a threshold effect.'))
    A(('note', '[Insert Figure 3 about here]'))
    A(('h2', '4.3 Parental investment: reinforcement or compensation'))
    A(('p', f'Table 3 and Figure 4 test whether parents compensate for weaker endowments. They do not. Each additional kilogram of birth weight predicts {f2(inv.b)} SD higher investment ({pf(inv.p)}) and {f2(bks.b)} SD more books ({pf(bks.p)}). Children estimated below 2.5 kg own {f2(abs(lbks.b))} SD fewer books ({pf(lbks.p)}), which survives correction within the panel, and mothers of these children hold lower educational aspirations ({f2(lasp.b)} on a four-point scale, {pf(lasp.p)}) and are less likely to aspire to college ({f2(lcol.b)}, {pf(lcol.p)}). Preterm birth is associated with lower aspirations ({f2(pasp.b)}, {pf(pasp.p)}). Mothers who rate their child\'s current health as better than village peers report more investment ({f2(hpi.b)} SD per scale point, {pf(hpi.p)}), consistent with a general efficiency motive that responds to visible health and not only to birth records. Estimates for investment are small relative to their standard errors, and only the books and aspiration results are individually distinguishable from zero. The pattern supports Hypothesis 3 in direction, with the caveat that the investment measures are maternal reports.'))
    A(('note', '[Insert Table 3 and Figure 4 about here]'))
    A(('h2', '4.4 Heterogeneity'))
    A(('p', f'Table 4 and Figure 5 present interactions between birth weight and seven moderators for four outcomes. Two results stand out, and both are exploratory. Where mothers expect a lot of old-age financial help from children, the birth weight gradient in the cognitive and academic composite is {f2(oa.b1)} SD per kilogram, against {f2(oa.b0)} elsewhere (interaction {f2(oa.b_int)}, SE {f2(oa.se_int)}, {pf(oa.p_int)}; q = {f2(oa.q_all)} across the 28 tests). Where mothers agree that parents should rely on sons, the height gradient is {f2(rs_h.b1)} SD per kilogram, against {f2(rs_h.b0)} elsewhere (interaction {f2(rs_h.b_int)}, {pf(rs_h.p_int)}; q = {f2(rs_h.q_all)}), and the investment gradient is {f2(rs_i.b1)} against {f2(rs_i.b0)} (interaction {f2(rs_i.b_int)}, {pf(rs_i.p_int)}). Six of the eight interaction coefficients for the two old-age moderators are positive, and all three with p below 0.05 are positive, which is consistent with Hypothesis 4, but the evidence is weak after correction for multiple testing.'))
    A(('p', f'Household resources moderate the investment gradient. Among households with above-median resources, each kilogram of birth weight predicts {f2(sl_i.b0)} SD more investment, whereas among households with below-median resources the gradient is {f2(sl_i.b1)} (interaction {f2(sl_i.b_int)}, {pf(sl_i.p_int)}; q = {f2(sl_i.q_all)}). Reinforcement appears where households can afford to differentiate. Child sex, the mother\'s rating of the village environment, the share of households using unsafe water, and the presence of a brother do not moderate the main gradients at conventional levels. The absence of village environmental moderation is informative given the interest in environmental conditions in the child development literature [[c:GrahamZivin2013;Currie2009air;Ebenstein2012]]: in this sample, a coarse and cross-sectional measure of water quality neither predicts the birth weight gradients nor leaves a trace in the negative controls.'))
    A(('note', '[Insert Table 4 and Figure 5 about here]'))
    A(('h2', '4.5 Robustness'))
    A(('p', f'Table 5 and Figure 6 vary the specification for the composite and for height. The height coefficient ranges from {f2(rng_h.b.min())} to {f2(rng_h.b.max())} SD per kilogram across twelve specifications, which include dropping household resources, dropping all demographic controls, replacing county with village fixed effects, clustering at the county, excluding preterm and gestation-unknown births, trimming birth weights to 2.0 to 4.5 kg, estimating separately for girls and boys, and adding place of delivery or current health relative to peers. Wild cluster bootstrap p-values for height are below 0.01 with clustering by village or county. The composite coefficient ranges from {f2(rng_c.b.min())} to {f2(rng_c.b.max())}, remains positive in every specification, and is not distinguishable from zero at the 5 percent level in any; its wild cluster bootstrap p-value is {f2(bc.p_wild_village)} by village. Inverse probability weights for attrition leave the estimates unchanged: the height coefficient is {f2(ipw.loc["z_height04","b_ipw"])} (unweighted {f2(ipw.loc["z_height04","b_unw"])}), and the 2009 literacy coefficient is {f2(ipw.loc["z_lit09","b_ipw"])} (unweighted {f2(ipw.loc["z_lit09","b_unw"])}).'))
    A(('note', '[Insert Table 5 and Figure 6 about here]'))
    A(('h2', '4.6 Endogeneity and measurement'))
    A(('p', f'Table 6 reports the identification checks. Adding controls does not reduce the height coefficient (restricted model {f2(ost_h.b_restricted)}, controlled model {f2(ost_h.b_full)}), so coefficient stability bounds are uninformative in the usual direction and offer no sign of selection on observables that would erode the estimate. For the cognitive and academic composite, the restricted and controlled coefficients are {f2(ost_c.b_restricted)} and {f2(ost_c.b_full)}. Selection on unobservables would need to be {f2(ost_c.delta_for_zero)} times as strong as selection on observables to reduce the estimate to zero, and the bias-adjusted coefficient at equal selection is {f2(ost_c.beta_star_delta1)}. These bounds say that a small positive cognitive gradient is not obviously an artifact of observable confounding, and they do not bound unobservable confounding that is correlated with the observables in unknown ways. For birth weight below 2.5 kg, the E-value for the height difference is {f2(ev.loc["z_height04","e_value_point"])} (confidence limit {f2(ev.loc["z_height04","e_value_ci"])}), and the E-value for the composite is {f2(ev.loc["z_cogacad","e_value_point"])}, with a confidence limit of {f2(ev.loc["z_cogacad","e_value_ci"])}, meaning that the cognitive difference is not distinguishable from no effect.'))
    A(('p', f'Negative control outcomes support the use of birth weight reports with one exception. Birth weight is unrelated to parents\' ages ({f2(nco.loc[FATHER,"b"])} years for fathers, {pf(nco.loc[FATHER,"p"])}; {f2(nco.loc[MOTHER,"b"])} for mothers, {pf(nco.loc[MOTHER,"p"])}), the presence of the father in the home ({pf(nco.loc["Father lives at home","p"])}), and the objectively measured unsafe-water share of the village ({pf(nco.loc["Village unsafe-water share","p"])}). It is positively related to the mother\'s own rating of the village environment ({f2(nco.loc["Village environment rating","b"])} per kilogram, {pf(nco.loc["Village environment rating","p"])}) and weakly to household resources ({pf(nco.loc["Household resource index","p"])}). The association with a purely subjective rating suggests that mothers who describe their surroundings favorably also report heavier births, a form of common reporting tendency that can inflate associations between subjective variables. The validation against measured height is the stronger evidence that the reports carry real information: the maternal report predicts a physical measure that the mother did not provide. Excluding children whose weight is reported as exactly 3.0 kg does not weaken the height gradient. For these reasons the village environment moderator in Table 4 is interpreted with caution, and conclusions rest on the objective village measure.'))
    A(('note', '[Insert Table 6 about here]'))
    # ------------------------------------------------------------------ 5 Discussion
    A(('h1', '5. Discussion'))
    A(('h2', '5.1 Principal findings'))
    A(('p', f'In a poor rural population, maternal reports of birth weight predict adolescent height with a gradient of {f2(bwh.b)} SD per kilogram, about {cm1:.1f} cm, which is stable across specifications and corrections. The same reports predict cognitive and academic performance with a gradient of {f2(bwc.b)} SD per kilogram that is positive but statistically uncertain. Parents respond to weaker endowments by investing less in learning, not more. Exploratory evidence suggests that the endowment gradients are steeper where mothers expect to depend on children in old age.'))
    A(('p', 'The contrast between height and cognition fits a model in which fetal growth sets physical growth trajectories that few postnatal inputs alter in poor settings, whereas cognitive and academic outcomes depend on a longer chain of schooling and family inputs that can dilute the endowment signal [[c:Victora2008;Cunha2006;GM2007]]. The reinforcing investment pattern adds a second reason to expect that cognitive gradients would widen at later ages: if resources flow to children who start stronger, differences compound. The cognitive gradient at ages 9 to 12 may therefore understate the cumulative effect, and the 2009 literacy gradient ' + f'({f2(g(T2, exposure="bw_c", outcome="z_lit09").b)} SD per kilogram, {pf(g(T2, exposure="bw_c", outcome="z_lit09").p)})' + ' is similar in size to the 2000 and 2004 gradients rather than larger, which does not support compounding in this sample.'))
    A(('h2', '5.2 Aging and the intergenerational contract'))
    A(('p', 'The old-age results are exploratory but connect two literatures that rarely meet. Models of the intergenerational contract imply that parents who plan to rely on children internalize the returns to investment, and the expectation of dependence on sons structures which children receive that investment [[c:Caldwell1976;Lee1998;Zimmer2003;Cai2006]]. The estimates are consistent with a stronger gradient in this group, and the investment gradient among mothers who favor reliance on sons has the expected sign. As rural China ages and pension coverage expands, the incentive to treat children as a source of old-age security should weaken. If the reinforcing pattern reflects old-age incentives, the expansion of rural pensions would soften it, and a testable implication is that the gradient in parental investment declines across cohorts exposed to pension coverage. The GSCF waves of 2015 and later cohorts could test this implication.'))
    A(('h2', '5.3 Limitations'))
    A(('p', 'Five limitations bound the conclusions. First, birth weight and gestation are recalled by mothers 9 to 12 years after birth, and the weight estimates are heaped. Classical error attenuates the gradients, whereas error correlated with household circumstances or the mother\'s outlook could bias them in either direction. The association with the subjective village rating shows that such correlation exists. Second, the analysis files do not contain parental education, household income, or ethnicity, which are recorded in household questionnaire files outside the analysis set. The household resource index and county fixed effects capture part of this variation, but omitted family background remains the main threat to the cognitive estimates. Third, sex was recorded in the 2004 files, so six percent of children have missing sex, handled by an indicator. Fourth, the investment measures are maternal reports, and the models cannot separate parental behavior from the mother\'s perception of the child. Fifth, the interactions are exploratory, with 28 tests and q-values above conventional thresholds for most of them.'))
    A(('p', 'A further limit concerns external exposures. Studies of environmental conditions and child development link pollution and water quality to birth outcomes and later human capital [[c:Currie2009air;Sanders2012;Chen2013;GrahamZivin2013]]. The GSCF files used here contain no measure of ambient air pollution, temperature, or precipitation, so the study cannot test such pathways. The village measure of drinking water source is the only objective environmental variable. Linking the children to gridded air pollution and climate records by county and birth month, the design used in climate and child development research, is a natural extension for cohorts born after the start of satellite records and for newer waves of the survey.'))
    A(('h2', '5.4 Implications'))
    A(('p', 'The results carry three implications. First, the physical consequences of weak birth endowments persist into adolescence in rural Gansu, which supports the case for maternal nutrition and perinatal care in poor regions. Second, the absence of parental compensation suggests that policies that reduce the cost of schooling or provide targeted support for children with weaker starts address a gap that families do not close themselves. Third, expectations about old-age support shape the allocation of investment across children, so the design of pensions in rural China interacts with early childhood equity.'))
    # ------------------------------------------------------------------ 6 Conclusion
    A(('h1', '6. Conclusion'))
    A(('p', f'Maternal reports of birth weight predict adolescent height in rural Gansu by {f2(bwh.b)} SD per kilogram, with a smaller and statistically uncertain gradient for cognitive and academic scores. Parents reinforce rather than compensate, and exploratory evidence links steeper gradients to expectations of old-age support from children. The study documents which associations are robust, which are fragile, and which data would sharpen them. Future work should combine recorded birth information, parental schooling and income, and external environmental exposures to separate the biological, familial, and environmental sources of early inequality in rural China.'))
    A(('h1', 'Data and code availability'))
    A(('p', 'The GSCF data are available through the survey\'s data release. The replication package contains the data construction scripts, Stata do-files, and Python scripts that reproduce every table and figure, and will be deposited in a public repository upon acceptance.'))
    A(('h1', 'References'))
    return B
